/**
 * The DSL's checks, before sending: field -> message, empty when nothing is
 * wrong. The server checks them again; this is so a form can say it first.
 * partial: an update that sends only what changed - what is required is not asked for.
 */
export function validateMember(value: Partial<MemberDTO> | null | undefined, partial = false): Record<string, string> {
    const errors: Record<string, string> = {};
    if (value == null) return errors;
    if (partial ? value.login === '' : (value.login == null || value.login === '')) errors.login = "로그인 ID is required";
    else if (value.login != null && String(value.login).length > 30) errors.login = "로그인 ID is at most 30 characters";
    else if (value.login != null && value.login !== '' && String(value.login).length < 4) errors.login = "로그인 ID is at least 4 characters";
    else if (value.login && !new RegExp("^(?:^[a-zA-Z0-9._-]+$)$").test(String(value.login))) errors.login = "login may use letters, digits and . _ -";
    if (partial ? value.password === '' : (value.password == null || value.password === '')) errors.password = "비밀번호 is required";
    else if (value.password != null && String(value.password).length > 255) errors.password = "비밀번호 is at most 255 characters";
    else if (value.password != null && value.password !== '' && String(value.password).length < 8) errors.password = "비밀번호 is at least 8 characters";
    else if (value.password && !new RegExp("^(?:^(?=.*[A-Za-z])(?=.*[0-9]).+$)$").test(String(value.password))) errors.password = "password needs a letter and a digit";
    if (partial ? value.name === '' : (value.name == null || value.name === '')) errors.name = "이름 is required";
    else if (value.name != null && String(value.name).length > 50) errors.name = "이름 is at most 50 characters";
    if (partial ? value.email === '' : (value.email == null || value.email === '')) errors.email = "이메일 is required";
    else if (value.email != null && String(value.email).length > 100) errors.email = "이메일 is at most 100 characters";
    else if (value.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(value.email))) errors.email = 'Email format invalid';
    if (value.phone != null && String(value.phone).length > 20) errors.phone = "전화번호 is at most 20 characters";
    if (value.company != null && String(value.company).length > 100) errors.company = "소속 회사 is at most 100 characters";
    return errors;
}

